--
-- Table structure for table `station_calendar_config`
--

DROP TABLE IF EXISTS `station_calendar_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `station_calendar_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `station_id` int(11) NOT NULL,
  `shift_schedule_enabled` tinyint(1) DEFAULT 1,
  `delivery_schedule_enabled` tinyint(1) DEFAULT 1,
  `calibration_events_enabled` tinyint(1) DEFAULT 1,
  `system_notifications_enabled` tinyint(1) DEFAULT 1,
  `default_shift_hours` varchar(50) DEFAULT '8:00 AM - 5:00 PM',
  `notification_lead_time_hours` int(11) DEFAULT 24 COMMENT 'Hours before event to notify',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_station_calendar` (`station_id`),
  KEY `updated_by` (`updated_by`),
  CONSTRAINT `station_calendar_config_ibfk_1` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `station_calendar_config_ibfk_2` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1415 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

