--
-- Table structure for table `station_fuel_config`
--

DROP TABLE IF EXISTS `station_fuel_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `station_fuel_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `station_id` int(11) NOT NULL,
  `fuel_type` varchar(50) NOT NULL COMMENT 'Diesel, Gasoline, Kerosene',
  `official_price_per_liter` decimal(10,2) NOT NULL,
  `tank_capacity` decimal(10,2) DEFAULT 0.00 COMMENT 'Maximum liters tank can hold',
  `calibration_schedule_days` int(11) DEFAULT 30 COMMENT 'How often to calibrate (days)',
  `variance_tolerance_percent` decimal(5,2) DEFAULT 5.00 COMMENT 'Acceptable variance %',
  `reconciliation_formula` varchar(255) DEFAULT '(present - previous - calibration) * price_per_liter',
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_station_fuel` (`station_id`,`fuel_type`),
  KEY `updated_by` (`updated_by`),
  KEY `idx_station_active` (`station_id`,`is_active`),
  CONSTRAINT `station_fuel_config_ibfk_1` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `station_fuel_config_ibfk_2` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4243 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

