--
-- Table structure for table `station_payment_config`
--

DROP TABLE IF EXISTS `station_payment_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `station_payment_config` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `station_id` int(11) NOT NULL,
  `payment_method` varchar(50) NOT NULL COMMENT 'Cash, Card, E-Wallet, Fleet/E-Fuel, Credit',
  `require_reference_number` tinyint(1) DEFAULT 0,
  `allow_partial_payment` tinyint(1) DEFAULT 1,
  `payment_status_default` enum('Paid','Pending') DEFAULT 'Pending',
  `audit_trail_enabled` tinyint(1) DEFAULT 1,
  `is_enabled` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_station_payment` (`station_id`,`payment_method`),
  KEY `updated_by` (`updated_by`),
  KEY `idx_station_enabled` (`station_id`,`is_enabled`),
  CONSTRAINT `station_payment_config_ibfk_1` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `station_payment_config_ibfk_2` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7071 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

